DECLARE @B bigint=(SELECT BatchId FROM ssis_flow.Context),@Previous bigint=(SELECT PreviousVersion FROM ssis_flow.Context),@Next bigint=(SELECT NextVersion FROM ssis_flow.Context);
IF @Previous IS NULL BEGIN
INSERT etl_raw.[ProductInventory]([ProductID],[LocationID],[Shelf],[Bin],[Quantity],[rowguid],[ModifiedDate],LoadBatchID) SELECT S.[ProductID],S.[LocationID],S.[Shelf],S.[Bin],S.[Quantity],S.[rowguid],S.[ModifiedDate],@B FROM ssis_flow.Delta_ProductInventory S;
INSERT stg.[ProductInventory]([ProductID],[LocationID],[Shelf],[Bin],[Quantity],[rowguid],[ModifiedDate],LoadBatchID) SELECT [ProductID],[LocationID],[Shelf],[Bin],[Quantity],[rowguid],[ModifiedDate],@B FROM etl_raw.[ProductInventory];
INSERT etl_v2.SourceChange SELECT @B,N'Production.ProductInventory','I',@Next,(SELECT R.[ProductID],R.[LocationID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),NULL FROM etl_raw.[ProductInventory] R;
END ELSE BEGIN
SELECT [ProductID],[LocationID],CONVERT(char(1),FlowOperation) SYS_CHANGE_OPERATION,FlowVersion SYS_CHANGE_VERSION INTO #CT_ProductInventory FROM ssis_flow.Delta_ProductInventory;
INSERT etl_v2.SourceChange SELECT @B,N'Production.ProductInventory',C.SYS_CHANGE_OPERATION,C.SYS_CHANGE_VERSION,(SELECT C.[ProductID],C.[LocationID] FOR JSON PATH,WITHOUT_ARRAY_WRAPPER),(SELECT R.* FOR JSON PATH,WITHOUT_ARRAY_WRAPPER,INCLUDE_NULL_VALUES) FROM #CT_ProductInventory C LEFT JOIN etl_raw.[ProductInventory] R ON R.[ProductID]=C.[ProductID] AND R.[LocationID]=C.[LocationID];
DELETE R FROM etl_raw.[ProductInventory] R JOIN #CT_ProductInventory C ON R.[ProductID]=C.[ProductID] AND R.[LocationID]=C.[LocationID] WHERE C.SYS_CHANGE_OPERATION='D';
UPDATE R SET R.[Shelf]=S.[Shelf],R.[Bin]=S.[Bin],R.[Quantity]=S.[Quantity],R.[rowguid]=S.[rowguid],R.[ModifiedDate]=S.[ModifiedDate],R.LoadBatchID=@B FROM etl_raw.[ProductInventory] R JOIN #CT_ProductInventory C ON R.[ProductID]=C.[ProductID] AND R.[LocationID]=C.[LocationID] JOIN ssis_flow.Delta_ProductInventory S ON S.[ProductID]=C.[ProductID] AND S.[LocationID]=C.[LocationID] WHERE C.SYS_CHANGE_OPERATION<>'D';
INSERT etl_raw.[ProductInventory]([ProductID],[LocationID],[Shelf],[Bin],[Quantity],[rowguid],[ModifiedDate],LoadBatchID) SELECT S.[ProductID],S.[LocationID],S.[Shelf],S.[Bin],S.[Quantity],S.[rowguid],S.[ModifiedDate],@B FROM #CT_ProductInventory C JOIN ssis_flow.Delta_ProductInventory S ON S.[ProductID]=C.[ProductID] AND S.[LocationID]=C.[LocationID] WHERE C.SYS_CHANGE_OPERATION<>'D' AND NOT EXISTS(SELECT 1 FROM etl_raw.[ProductInventory] R WHERE R.[ProductID]=S.[ProductID] AND R.[LocationID]=S.[LocationID]);
INSERT stg.[ProductInventory]([ProductID],[LocationID],[Shelf],[Bin],[Quantity],[rowguid],[ModifiedDate],LoadBatchID) SELECT R.[ProductID],R.[LocationID],R.[Shelf],R.[Bin],R.[Quantity],R.[rowguid],R.[ModifiedDate],@B FROM etl_raw.[ProductInventory] R JOIN #CT_ProductInventory C ON R.[ProductID]=C.[ProductID] AND R.[LocationID]=C.[LocationID] WHERE C.SYS_CHANGE_OPERATION<>'D';
END;